import{c as t,Q as o,j as d,m as r}from"./chunks/framework.t4rEqR7d.js";const h=JSON.parse('{"title":"pagentv4 重构修复清单","description":"","frontmatter":{},"headers":[],"relativePath":"pagentv4/refactor-triage.md","filePath":"pagentv4/refactor-triage.md"}'),n={name:"pagentv4/refactor-triage.md"};function a(c,e,s,p,i,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="pagentv4-重构修复清单" tabindex="-1">pagentv4 重构修复清单 <a class="header-anchor" href="#pagentv4-重构修复清单" aria-label="Permalink to &quot;pagentv4 重构修复清单&quot;">​</a></h1><p><strong>范围</strong>:<code>src/pagentv4/</code>(~6600 行)。 <strong>分级定义</strong>:</p><ul><li><strong>P0</strong>:结构性问题,已产生或必然产生行为不一致/维护阻塞,建议尽快处理。</li><li><strong>P1</strong>:显著冗余或约定不一致,本迭代或下个迭代内处理。</li><li><strong>P2</strong>:可读性/风格层面,可择机处理,不影响功能。</li></ul><hr><h2 id="p0" tabindex="-1">P0 <a class="header-anchor" href="#p0" aria-label="Permalink to &quot;P0&quot;">​</a></h2><h3 id="p0-1-runner-未继承-baserunner-loopcoreadapter-已存在三份实现并发生行为漂移" tabindex="-1">P0-1 Runner 未继承 BaseRunner,LoopCoreAdapter 已存在三份实现并发生行为漂移 <a class="header-anchor" href="#p0-1-runner-未继承-baserunner-loopcoreadapter-已存在三份实现并发生行为漂移" aria-label="Permalink to &quot;P0-1 Runner 未继承 BaseRunner,LoopCoreAdapter 已存在三份实现并发生行为漂移&quot;">​</a></h3><p><strong>问题</strong><code>VanillaRunner</code>、<code>BaseRunner</code>、<code>Runner</code> 各自独立实现了同一套 <code>LoopCoreAdapter</code> 协议方法(<code>execute_tool</code> / <code>emit</code> / <code>stream_agent_events</code> / <code>emit_tool_events</code> / <code>after_continuing</code> / <code>after_run_end</code> / <code>run</code>)。其中 <code>ChatRunner</code>、<code>CodeRunner</code> 正确继承 <code>BaseRunner</code>,但功能最全的 <a href="./src/pagentv4/runtime/runner.py.html#L41"><code>Runner</code></a> 不继承 <code>BaseRunner</code>,而是平行重写。<code>LoopCoreAdapter</code> 是 <code>Protocol</code>(duck typing),不提供共享实现。</p><p><strong>依据</strong></p><ul><li><a href="./src/pagentv4/runtime/runner.py.html#L41"><code>Runner</code></a> 与 <a href="./src/pagentv4/runtime/base_runner.py.html#L45"><code>BaseRunner</code></a> 为平级类。</li><li><code>emit_tool_events</code> 已发生行为差异:<a href="./src/pagentv4/runtime/runner.py.html#L158-L186">Runner 版</a> 走 <code>run_tool_with_hooks</code>,<a href="./src/pagentv4/runtime/base_runner.py.html#L109-L129">BaseRunner 版</a> 直接 <code>execute_tool</code>。</li></ul><p><strong>影响</strong> BaseRunner 的后续改动不会自动传导到 Runner,差异会持续累积。三份近重复实现增加维护成本与回归风险。</p><p><strong>建议</strong> 让 <code>Runner</code> 继承 <code>BaseRunner</code>,将 inbound/cancel/checkpoint 与 tool hooks 抽成可叠加的能力(基类方法或 mixin),保留单一 adapter 实现作为默认。</p><h4 id="详细分析-三个-runner-的相同与不同" tabindex="-1">详细分析:三个 runner 的相同与不同 <a class="header-anchor" href="#详细分析-三个-runner-的相同与不同" aria-label="Permalink to &quot;详细分析:三个 runner 的相同与不同&quot;">​</a></h4><p>逐方法比对(<code>LoopCoreAdapter</code> 协议要求的 7 个方法 + 资源生命周期):</p><table tabindex="0"><thead><tr><th>方法</th><th>VanillaRunner</th><th>BaseRunner</th><th>Runner</th><th>结论</th></tr></thead><tbody><tr><td><code>execute_tool</code></td><td><code>tool.acall</code></td><td>同左</td><td>同左</td><td>三者逐字相同(假重复)</td></tr><tr><td><code>stream_agent_events</code></td><td>generate→append→to_event</td><td>同左</td><td>同左</td><td>三者逐字相同(假重复)</td></tr><tr><td><code>emit</code></td><td>透传</td><td>透传</td><td>透传 <strong>+ inbound drain</strong></td><td>Vanilla=Base;Runner 多检查点</td></tr><tr><td><code>emit_tool_events</code></td><td>直接 <code>execute_tool</code></td><td>直接 <code>execute_tool</code></td><td>走 <code>run_tool_with_hooks</code></td><td>Vanilla=Base;Runner 多 hooks</td></tr><tr><td><code>after_continuing</code> / <code>after_run_end</code></td><td>no-op</td><td><code>flush</code></td><td><code>flush</code></td><td>Vanilla 不持久化;Base=Runner</td></tr><tr><td><code>run</code> 主体</td><td>ensure→append→loop→project</td><td>同左</td><td>同左,但包 <code>_events</code> 捕获 <code>RunCancelled</code></td><td>Vanilla=Base;Runner 多 cancel 处理</td></tr><tr><td><code>close</code></td><td>无</td><td>关 store + sandbox 可选(None 守卫)</td><td>关 store + sandbox 必有</td><td>资源生命周期不同</td></tr></tbody></table><p><strong>为什么需要分开写(本质)</strong>:三个类不是三个不同的引擎,而是「同一套循环骨架 + 4 个正交能力开关」的组合。当前把这 4 个开关的取值焊死成 3 个并列类,共享骨架(<code>execute_tool</code> / <code>stream_agent_events</code> / <code>run</code> 主体 / <code>emit</code> 透传)被复制 3 遍,漂移由此产生(<code>emit_tool_events</code> 已在 Runner 与 Base 之间分叉)。</p><table tabindex="0"><thead><tr><th>能力轴</th><th>Vanilla</th><th>Base</th><th>Runner</th></tr></thead><tbody><tr><td>① inbound(steer / cancel / permit)</td><td>✗</td><td>✗</td><td>✓</td></tr><tr><td>② tool hooks(before / after)</td><td>✗</td><td>✗</td><td>✓</td></tr><tr><td>③ 持久化(thread / store / flush / close)</td><td>✗</td><td>✓</td><td>✓</td></tr><tr><td>④ sandbox 必备</td><td>✗</td><td>可选</td><td>✓</td></tr></tbody></table><p><strong>收敛方案</strong>:抽 <code>LoopAdapter</code> 基类承载骨架,三类只覆写真差异点:</p><ul><li><code>LoopAdapter</code>:<code>execute_tool</code> / <code>stream_agent_events</code> / <code>emit</code>(透传)/ <code>emit_tool_events</code>(直接执行)/ <code>run</code>(直接 loop)/ <code>after_*</code>(no-op 默认)。</li><li><code>BaseRunner(LoopAdapter)</code>:加 thread/store/sandbox/skills;覆写 <code>after_*</code>→flush;<code>close</code>(sandbox None 守卫);<code>from_spec</code>。</li><li><code>Runner(BaseRunner)</code>:加 inbound/hooks;覆写 <code>emit</code>(drain)/ <code>emit_tool_events</code>(hooks)/ <code>run</code>(RunCancelled);inbound 控制面;<code>create</code> 工厂。</li><li><code>VanillaRunner(LoopAdapter)</code>:仅 <code>__init__(agent, messages=)</code>,其余全继承,<code>after_*</code> 用默认 no-op。</li></ul><p>消重后:<code>execute_tool</code> / <code>stream_agent_events</code> / <code>run</code> 主体 / <code>emit</code> 默认版从 3 份降为 1 份。公共 API(<code>Runner.create</code> / <code>runner.inbound</code> / <code>BaseRunner.from_spec</code> / <code>VanillaRunner(agent, messages=)</code> 等)保持不变。</p><hr><h3 id="p0-2-agent-restored-py-为死代码" tabindex="-1">P0-2 <code>agent_restored.py</code> 为死代码 <a class="header-anchor" href="#p0-2-agent-restored-py-为死代码" aria-label="Permalink to &quot;P0-2 `agent_restored.py` 为死代码&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/core/agent_restored.py.html"><code>core/agent_restored.py</code></a> 定义的 <code>Agent</code> 类与 <a href="./src/pagentv4/core/agent.py.html#L8"><code>agent.py</code></a> 中的 <code>AgentCore</code> 逐字相同,唯一差异是 import 写 <code>Provider</code> 还是 <code>ProviderProtocol</code>(<code>agent.py</code> 末尾另 <code>Agent = AgentCore</code> 别名)。</p><p><strong>依据</strong> 全仓引用检索:<code>agent_restored</code> 命中 0 处。<code>core/__init__.py</code> 与顶层 <code>__init__.py</code> 的 <code>Agent</code>/<code>AgentCore</code> 均从 <code>agent.py</code> 导入。</p><p><strong>影响</strong> 无功能影响,但属于重构残留,且 <code>Agent</code> / <code>AgentCore</code> 双名降低可读性。</p><p><strong>建议</strong> 删除 <a href="./src/pagentv4/core/agent_restored.py.html"><code>agent_restored.py</code></a>,保留单一类定义与一个规范对外名。</p><hr><h2 id="p1" tabindex="-1">P1 <a class="header-anchor" href="#p1" aria-label="Permalink to &quot;P1&quot;">​</a></h2><h3 id="p1-1-runner-create-与-runner-open-完全等价" tabindex="-1">P1-1 <code>Runner.create</code> 与 <code>Runner.open</code> 完全等价 <a class="header-anchor" href="#p1-1-runner-create-与-runner-open-完全等价" aria-label="Permalink to &quot;P1-1 `Runner.create` 与 `Runner.open` 完全等价&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/runtime/runner.py.html#L330-L353"><code>Runner.open</code></a> 仅转调 <code>Runner.create</code>,参数列表完全一致,注释自述&quot;兼容旧入口&quot;。</p><p><strong>依据</strong><a href="./src/pagentv4/runtime/runner.py.html#L330-L353">runner.py:330-353</a>。</p><p><strong>影响</strong> 对外暴露两个等价入口,增加 API 面与文档负担。</p><p><strong>建议</strong> 移除 <code>open</code>,或标记 <code>@deprecated</code> 后按版本删除。</p><hr><h3 id="p1-2-messages-的-append-合并与-export-折叠双重维护" tabindex="-1">P1-2 <code>Messages</code> 的 append 合并与 export 折叠双重维护 <a class="header-anchor" href="#p1-2-messages-的-append-合并与-export-折叠双重维护" aria-label="Permalink to &quot;P1-2 `Messages` 的 append 合并与 export 折叠双重维护&quot;">​</a></h3><p><strong>问题</strong> 存储侧 <a href="./src/pagentv4/core/message.py.html#L249-L302"><code>__iadd__</code> + <code>can_merge_messages</code></a> 在追加时合并相邻同 turn 同类型 assistant chunk;导出侧 <a href="./src/pagentv4/core/message.py.html#L345-L424"><code>to_openai</code></a> 再次折叠所有 assistant chunk。两套逻辑覆盖范围不一致:append 合并仅处理 text/text、thinking/thinking,export 折叠覆盖全部。</p><p><strong>依据</strong><a href="./src/pagentv4/core/message.py.html#L249-L266"><code>can_merge_messages</code></a> 与 <a href="./src/pagentv4/core/message.py.html#L381-L419"><code>to_openai</code></a>。</p><p><strong>影响</strong> 任一侧 schema 变更时,另一侧需同步,存在隐性不一致风险。</p><p><strong>建议</strong> 收敛为单一折叠点(建议保留 export 侧折叠,移除 append 侧合并),合并语义只在一处定义。</p><hr><h3 id="p1-3-chatrunner-from-toml-与-coderunner-from-toml-构造约定不一致" tabindex="-1">P1-3 <code>ChatRunner.from_toml</code> 与 <code>CodeRunner.from_toml</code> 构造约定不一致 <a class="header-anchor" href="#p1-3-chatrunner-from-toml-与-coderunner-from-toml-构造约定不一致" aria-label="Permalink to &quot;P1-3 `ChatRunner.from_toml` 与 `CodeRunner.from_toml` 构造约定不一致&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/runtime/chat_runner.py.html#L99-L101"><code>ChatRunner.from_toml</code></a> 使用 <code>instance = cls.__new__(cls)</code> 绕过 <code>__init__</code>,再手动调用 <code>BaseRunner.__init__</code>;而 <a href="./src/pagentv4/runtime/code_runner.py.html#L291-L301"><code>CodeRunner.from_toml</code></a> 使用正常 <code>cls(..., spec=spec)</code> 路径。</p><p><strong>依据</strong><a href="./src/pagentv4/runtime/chat_runner.py.html#L99-L101">chat_runner.py:99-101</a> 对比 <a href="./src/pagentv4/runtime/code_runner.py.html#L291-L301">code_runner.py:291-301</a>。</p><p><strong>影响</strong><code>__new__</code> 绕过 <code>__init__</code> 对父类演化敏感;同一项目两种构造写法无统一约定。</p><p><strong>建议</strong> 统一为 <code>cls(...)</code> 构造路径;如需区分 spec 来源,以构造参数(如 <code>spec=</code>)传入。</p><hr><h3 id="p1-4-别名层放大对外-api-面" tabindex="-1">P1-4 别名层放大对外 API 面 <a class="header-anchor" href="#p1-4-别名层放大对外-api-面" aria-label="Permalink to &quot;P1-4 别名层放大对外 API 面&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/runtime/__init__.py.html#L41-L44">runtime/__init__.py:41-44</a> 定义 <code>ChatAgent=ChatRunner</code> / <code>CodeAgent=CodeRunner</code> / <code>ThreadAgent=Runner</code> / <code>VanillaAgent=VanillaRunner</code>,叠加 <code>core</code> 的 <code>Agent=AgentCore</code>。</p><p><strong>影响</strong> 对每个概念暴露 2 个等价名,使用者难以判断规范写法。</p><p><strong>建议</strong> 每个概念保留单一规范名,别名在文档中标注后逐步移除,或集中到一个显式 <code>aliases</code> 子模块。</p><hr><h3 id="p1-5-emit-方法类型标注与实现不符" tabindex="-1">P1-5 <code>emit</code> 方法类型标注与实现不符 <a class="header-anchor" href="#p1-5-emit-方法类型标注与实现不符" aria-label="Permalink to &quot;P1-5 `emit` 方法类型标注与实现不符&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/runtime/runner.py.html#L130-L138"><code>Runner.emit</code></a> 与 <a href="./src/pagentv4/runtime/loop_core.py.html#L16"><code>LoopCoreAdapter.emit</code></a> 标注为 <code>-&gt; AsyncIterator</code>,但方法体为 <code>async def</code> + <code>yield</code>,实际是 async generator(应为 <code>AsyncGenerator</code>)。此外 <code>emit</code> 这层间接对 <code>BaseRunner</code> / <code>VanillaRunner</code> 是纯透传(仅 <code>Runner</code> 用它插入 inbound drain)。</p><p><strong>依据</strong><a href="./src/pagentv4/runtime/runner.py.html#L130-L138">runner.py:130-138</a>、<a href="./src/pagentv4/runtime/base_runner.py.html#L94-L96">base_runner.py:94-96</a>、<a href="./src/pagentv4/runtime/vanilla.py.html#L54-L56">vanilla.py:54-56</a>。</p><p><strong>影响</strong> 类型检查无法正确推断;透传层对非 inbound 实现是噪声。</p><p><strong>建议</strong> 修正标注为 <code>AsyncGenerator</code>;评估仅在需要 inbound drain 的实现中保留 <code>emit</code> 覆写。</p><hr><h2 id="p2" tabindex="-1">P2 <a class="header-anchor" href="#p2" aria-label="Permalink to &quot;P2&quot;">​</a></h2><h3 id="p2-1-provider-子类仅为常量差异" tabindex="-1">P2-1 Provider 子类仅为常量差异 <a class="header-anchor" href="#p2-1-provider-子类仅为常量差异" aria-label="Permalink to &quot;P2-1 Provider 子类仅为常量差异&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/core/provider.py.html#L84-L116"><code>Provider</code> 的 7 个子类</a>(DeepSeek/Kimi/MiMo/LongCat/Ollama/Vllm/Sglang)各自仅覆盖 <code>API_KEY_ENV_VAR</code> 与 <code>BASE_URL</code> 两个类属性。</p><p><strong>影响</strong> 配置被硬编码为类型,新增 provider 需新增类。</p><p><strong>建议</strong> 改为 <code>Provider(&quot;deepseek&quot;)</code> + 预设注册表(<code>{&quot;deepseek&quot;: {...}}</code>)。</p><hr><h3 id="p2-2-coderunner-lazy-init-使-self-agent-语义可变" tabindex="-1">P2-2 <code>CodeRunner</code> lazy init 使 <code>self.agent</code> 语义可变 <a class="header-anchor" href="#p2-2-coderunner-lazy-init-使-self-agent-语义可变" aria-label="Permalink to &quot;P2-2 `CodeRunner` lazy init 使 `self.agent` 语义可变&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/runtime/code_runner.py.html#L142-L173"><code>CodeRunner</code></a> 保留 <code>base_agent</code>,在 <code>ensure_initialized</code> 时用 <a href="./src/pagentv4/runtime/code_runner.py.html#L45-L57"><code>build_code_agent</code></a> 重建 <code>self.agent</code>。</p><p><strong>影响</strong><code>self.agent</code> 在 <code>run</code> 前后可能为不同对象,<code>tools</code> 在初始化前为空。</p><p><strong>建议</strong> 收敛为单一工厂路径(仅 <code>create</code>),或文档化&quot;agent 在首次 run 前为占位&quot;。</p><hr><h3 id="p2-3-loop-core-末尾不可达分支" tabindex="-1">P2-3 <code>loop_core</code> 末尾不可达分支 <a class="header-anchor" href="#p2-3-loop-core-末尾不可达分支" aria-label="Permalink to &quot;P2-3 `loop_core` 末尾不可达分支&quot;">​</a></h3><p><strong>问题</strong><a href="./src/pagentv4/runtime/loop_core.py.html#L168">loop_core.py:168</a> <code>raise RuntimeError(&quot;unreachable&quot;)</code>。因 <code>AgentCore</code> 构造已拒绝 <code>max_turns &lt; 1</code>,该行确实不可达。</p><p><strong>建议</strong> 改为 <code>assert False, &quot;unreachable&quot;</code> 或直接移除循环外代码。</p><hr><h2 id="汇总" tabindex="-1">汇总 <a class="header-anchor" href="#汇总" aria-label="Permalink to &quot;汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>编号</th><th>概要</th><th>主要文件</th></tr></thead><tbody><tr><td>P0</td><td>P0-1</td><td>Runner 不继承 BaseRunner,adapter 三份实现且已漂移</td><td>runtime/runner.py, base_runner.py, vanilla.py</td></tr><tr><td>P0</td><td>P0-2</td><td>agent_restored.py 死代码</td><td>core/agent_restored.py</td></tr><tr><td>P1</td><td>P1-1</td><td>Runner.create / open 等价</td><td>runtime/runner.py</td></tr><tr><td>P1</td><td>P1-2</td><td>Messages 双重折叠逻辑</td><td>core/message.py</td></tr><tr><td>P1</td><td>P1-3</td><td>from_toml 构造约定不一致</td><td>runtime/chat_runner.py, code_runner.py</td></tr><tr><td>P1</td><td>P1-4</td><td>别名层放大 API 面</td><td>runtime/__init__.py, core/__init__.py</td></tr><tr><td>P1</td><td>P1-5</td><td>emit 类型标注不符</td><td>runtime/runner.py, loop_core.py</td></tr><tr><td>P2</td><td>P2-1</td><td>Provider 子类仅常量差异</td><td>core/provider.py</td></tr><tr><td>P2</td><td>P2-2</td><td>CodeRunner lazy init 致 agent 可变</td><td>runtime/code_runner.py</td></tr><tr><td>P2</td><td>P2-3</td><td>不可达分支</td><td>runtime/loop_core.py</td></tr></tbody></table><p><strong>建议顺序</strong>:P0-2 与 P1-1、P2-3 为低风险删除/收敛动作,可先行;P0-1 为核心结构调整,建议在其基础上统一 P1-3、P1-5。</p><hr><h2 id="执行记录-2026-07-10" tabindex="-1">执行记录(2026-07-10) <a class="header-anchor" href="#执行记录-2026-07-10" aria-label="Permalink to &quot;执行记录(2026-07-10)&quot;">​</a></h2><p>按本清单完成批次一(P0)+ 批次二(P1/P2)。验证:<code>pytest tests/</code> <strong>441 passed / 4 skipped</strong>;<code>ruff check src/pagentv4</code> <strong>All checks passed</strong>。</p><h3 id="已完成" tabindex="-1">已完成 <a class="header-anchor" href="#已完成" aria-label="Permalink to &quot;已完成&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>处理</th></tr></thead><tbody><tr><td>P0-1</td><td>新增 <code>runtime/loop_adapter.py</code> 承载循环骨架;BaseRunner / VanillaRunner / Runner 重组为 <code>LoopAdapter → BaseRunner → Runner</code>(Vanilla 直接继承 LoopAdapter)继承链;<code>run</code> 仅写一次,Runner 通过覆写 <code>_event_source</code> 注入 <code>RunCancelled</code>。消除三份 adapter 实现。</td></tr><tr><td>P0-2</td><td>删除 <code>core/agent_restored.py</code> 及 <code>pyproject.toml</code> coverage omit 对应条目。</td></tr><tr><td>P1-1</td><td>删除 <code>Runner.open</code>(= <code>create</code>,0 调用者)。</td></tr><tr><td>P1-3</td><td><code>ChatRunner.__init__</code> 增加 <code>spec</code> 参数,<code>from_toml</code> 改用 <code>cls(...)</code> 正常构造,去掉 <code>cls.__new__</code>。</td></tr><tr><td>P1-4</td><td>保留全部别名(测试硬断言 <code>XxxAgent is XxxRunner</code>),在 <code>runtime/__init__.py</code> 与 <code>core/agent.py</code> 加注释标注规范名。</td></tr><tr><td>P1-5</td><td><code>loop_adapter.py</code> / <code>runner.py</code> / <code>loop_core.py</code> 的 async generator 方法返回标注 <code>AsyncIterator</code> → <code>AsyncGenerator</code>。</td></tr><tr><td>P2-2</td><td><code>CodeRunner.ensure_initialized</code> docstring 文档化 <code>self.agent</code> 在首次 run 前为占位。</td></tr><tr><td>P2-3</td><td><code>loop_core</code> 末尾 <code>raise RuntimeError(&quot;unreachable&quot;)</code> → <code>assert False, &quot;unreachable&quot;</code>。</td></tr></tbody></table><h3 id="降级-深入核实后调整结论" tabindex="-1">降级(深入核实后调整结论) <a class="header-anchor" href="#降级-深入核实后调整结论" aria-label="Permalink to &quot;降级(深入核实后调整结论)&quot;">​</a></h3><p><strong>P1-2(Messages 双重折叠)</strong>:原建议&quot;移除 append 合并、保留 export 折叠&quot;。核实发现 append 合并是被 <code>test_runner_accumulates_assistant_chunks_in_messages</code> 守护的有意设计——流式 reasoning/text delta 需累积成紧凑行(<code>data[2].content.text == &quot;let me think&quot;</code>)。它与 <code>to_openai</code> 折叠职责不同(append = 同类型 delta 累积,export = chunk → OpenAI dict 结构转换),并非纯冗余。改为在 <code>message.py</code> 的 <code>to_openai</code> 加分工注释,不移除合并逻辑。</p><p><strong>P2-1(Provider 子类)</strong>:原建议&quot;改为预设注册表&quot;。核实发现 7 个子类是 public API,被 <code>app/repl.py</code>、<code>test_pagentv4_provider</code>(断言 <code>.apikey</code> / <code>.base_url</code> 类属性)、<code>test_pagentv4_thread_session</code> 直接使用。消除子类属破坏性变更,需先迁移调用方与测试。本次不改实现,列为独立迁移任务。</p>',82)])])}const g=t(n,[["render",a]]);export{h as __pageData,g as default};
